    out = [row[:] for row in grid]
    # Find full-width horizontal divider (color 2); join aligned matching
    # nonzero markers above and below it with color 4 on the upper side.
    div = next(i for i, row in enumerate(grid) if row and all(v == 2 for v in row))
    top = next((r for r in grid[:div] if any(r)), [])
    bottom = next((r for r in grid[div+1:] if any(r)), [])
    if top and bottom:
        for c, (a, b) in enumerate(zip(top, bottom)):
            if a != 0 and a == b:
                for r in range(1, div):
                    if out[r][c] == 0:
                        out[r][c] = 4
    return out
